package net.civeira.phylax.feature.access.userscopeconsent.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userscopeconsent.domain.UserScopeConsent;
import net.civeira.phylax.feature.access.userscopeconsent.domain.valueobject.ScopeVO;

class ScopeValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of scope of user scope consent")
  void test_scope_value_holder_assign_plain_value() {
    Object holder = new Object();
    ScopeValueHolder<Object> value = new ScopeValueHolder<>(holder);
    Assertions.assertSame(holder, value.scope("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getScopeValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getScope().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.scopeNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getScopeValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getScope().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of scope of user scope consent")
  void test_scope_value_holder_assign_value_object() {
    Object holder = new Object();
    ScopeValueHolder<Object> value = new ScopeValueHolder<>(holder);
    ScopeVO vo = ScopeVO.from("one");
    Assertions.assertFalse(value.getScopeValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.scope(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getScopeValue().orElseThrow());
    Assertions.assertSame(holder, value.scope(Optional.empty()));
    Assertions.assertFalse(value.getScopeValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.scope(Optional.of(vo)));
    Assertions.assertSame(vo, value.getScopeValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of scope of user scope consent against the original")
  void test_scope_value_holder_read() {
    Object holder = new Object();
    ScopeValueHolder<Object> value = new ScopeValueHolder<>(holder);
    ScopeVO vo = ScopeVO.from("one");
    ScopeVO other = ScopeVO.from("one");
    UserScopeConsent original = Mockito.mock(UserScopeConsent.class);
    Mockito.when(original.getScopeValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readScope(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readScope(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.scope(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readScope(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readScope(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of scope of user scope consent")
  void test_scope_value_holder_unset() {
    Object holder = new Object();
    ScopeValueHolder<Object> value = new ScopeValueHolder<>(holder);
    ScopeVO vo = ScopeVO.from("one");
    value.scope(vo);
    Assertions.assertSame(holder, value.unsetScopeIfMatches("scope_other"));
    Assertions.assertTrue(value.getScopeValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetScopeIfMatches("scope"));
    Assertions.assertFalse(value.getScopeValue().isPresent(),
        "The field name must clear the value");
    value.scope(vo);
    Assertions.assertSame(holder, value.unsetScope());
    Assertions.assertFalse(value.getScopeValue().isPresent(), "Unset must clear the value");
  }
}
